<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';admin_required();[$from,$to]=report_date_range(scalar_string($_GET['from']??''),scalar_string($_GET['to']??''));$report=management_report($from,$to);
if(ob_get_level()>0)ob_end_clean();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="mousavi-report-'.$from.'-'.$to.'.csv"');header('X-Content-Type-Options: nosniff');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');
$safe=static function(mixed $value):mixed{if(is_string($value)&&preg_match('/^[=+\-@]/',$value))return "'".$value;return $value;};
fputcsv($out,['گزارش فروشگاه گلریزان',$from,$to]);fputcsv($out,['تعداد سفارش',$report['summary']['orders']]);fputcsv($out,['فروش خالص پس از بازپرداخت (تومان)',$report['summary']['revenue']]);fputcsv($out,['بازپرداخت تکمیل‌شده (تومان)',$report['summary']['refunds']]);fputcsv($out,['تخفیف‌ها (تومان)',$report['summary']['discounts']]);fputcsv($out,[]);fputcsv($out,['فروش روزانه']);fputcsv($out,['تاریخ','تعداد سفارش','فروش خالص (تومان)']);foreach($report['daily'] as $row)fputcsv($out,[$row['day'],$row['orders_count'],$row['total']]);fputcsv($out,[]);fputcsv($out,['محصولات پرفروش']);fputcsv($out,['محصول','تعداد','فروش خالص تخصیص‌یافته']);foreach($report['top_products'] as $row)fputcsv($out,[$safe($row['title']),$row['quantity'],$row['gross']]);fputcsv($out,[]);fputcsv($out,['مشتریان برتر']);fputcsv($out,['نام','موبایل','تعداد سفارش','خرید خالص']);foreach($report['top_customers'] as $row)fputcsv($out,[$safe($row['customer_name']),$row['phone'],$row['orders_count'],$row['total']]);fputcsv($out,[]);fputcsv($out,['کدهای تخفیف']);fputcsv($out,['کد','سفارش','تخفیف','فروش خالص']);foreach($report['coupons'] as $row)fputcsv($out,[$safe($row['coupon_code']),$row['orders_count'],$row['discount_total'],$row['total']]);fputcsv($out,[]);fputcsv($out,['سبدهای رهاشده']);fputcsv($out,['وضعیت','تعداد','ارزش']);foreach($report['abandoned'] as $row)fputcsv($out,[$row['status'],$row['count'],$row['subtotal']]);fclose($out);exit;
